'use client';

import { useSession } from '@/registry/ndeko/hooks/use-session';
import {
  pressedSolidOf,
  spokenUnless,
} from '@/registry/ndeko/lib/demonstration';
import { PlayIcon, RocketIcon, XIcon } from '@/registry/ndeko/lib/icons';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { BrandTile } from '@/registry/ndeko/ui/brand-tile';
import { Button } from '@/registry/ndeko/ui/button';
import { Swap } from '@/registry/ndeko/ui/chat-motion';
import { ClockGate } from '@/registry/ndeko/ui/live-duration';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import { MorphButton, type MorphState } from '@/registry/ndeko/ui/morph-button';
import { ReplayButton } from '@/registry/ndeko/ui/replay-button';
import { Segments, type Segment } from '@/registry/ndeko/ui/segments';

import { CaseDetail } from './case-detail';
import { CaseGrid } from './case-grid';
import { CELL_WORD, StatusCell } from './cells';
import { caseOf, CASES, PROMPT, TARGETS, type EvalCase } from './data';
import {
  blockedCountOf,
  candidateStatusOf,
  canShip,
  INITIAL,
  isRegression,
  LOOP_AFTER_MS,
  matchesFilter,
  reducer,
  RESTING,
  SCRIPT,
  undecidedCountOf,
  type CellStatus,
  type EvalState,
  type Filter,
  type RunPhase,
} from './session';
import { Versions } from './versions';

const SESSION = {
  reducer,
  initial: INITIAL,
  resting: RESTING,
  script: SCRIPT,
  loopAfter: LOOP_AFTER_MS,
};

const FILTERS: Segment<Filter>[] = [
  { value: 'all', label: 'All' },
  { value: 'failing', label: 'Failing' },
  { value: 'regressions', label: 'Regressions' },
];

const RUN_STATE: Record<RunPhase, MorphState> = {
  idle: 'idle',
  running: 'busy',
  done: 'done',
};

const RUN_LABELS: Record<MorphState, string> = {
  idle: 'Run evals',
  busy: 'Running',
  done: `Ran ${CASES.length} cases`,
};

const SHIP_LABELS: Record<MorphState, string> = {
  idle: `Ship ${TARGETS.candidate.version}`,
  busy: 'Shipping',
  done: 'Shipped',
};

const LEGEND: { status: CellStatus; meaning: string }[] = [
  { status: 'pass', meaning: 'The grader accepted the reply' },
  { status: 'fail', meaning: 'The reply misses what was expected' },
  { status: 'flaky', meaning: 'It passes on some runs only' },
  { status: 'running', meaning: 'The case is with the model now' },
  { status: 'queued', meaning: 'It waits for a free slot' },
];

function regressionsWordOf(count: number) {
  if (count === 1) {
    return '1 regression';
  }
  return `${count} regressions`;
}

function casesWordOf(count: number) {
  if (count === 1) {
    return '1 case';
  }
  return `${count} cases`;
}

function shipHintOf(state: EvalState) {
  const version = TARGETS.candidate.version;
  if (state.ship === 'done') {
    return `${version} answers every new conversation`;
  }
  if (state.ship === 'busy') {
    return `Moving conversations to ${version}`;
  }
  if (state.phase === 'idle') {
    return `Run the evals before ${version} ships`;
  }
  if (state.phase === 'running') {
    return 'Shipping waits for the run to end';
  }
  const undecided = undecidedCountOf(state);
  if (undecided > 0) {
    return `${regressionsWordOf(undecided)} to decide`;
  }
  const blocked = blockedCountOf(state);
  if (blocked > 0) {
    return `${regressionsWordOf(blocked)} blocked: fix the prompt and run again`;
  }
  return 'Every regression is decided';
}

function runVariantOf(phase: RunPhase) {
  if (phase === 'idle') {
    return 'default';
  }
  return 'outline';
}

function shipVariantOf(isReady: boolean) {
  if (isReady) {
    return 'default';
  }
  return 'outline';
}

function Legend() {
  return (
    <div className='flex flex-col gap-3'>
      <div className='flex flex-col gap-1'>
        <h2 className='text-sm font-medium'>
          Pick a case to read both replies
        </h2>
        <p className='text-muted-foreground text-[13px]'>
          A regression opens with the part that fails marked, and waits for your
          decision.
        </p>
      </div>
      <ul className='flex flex-col'>
        {LEGEND.map((entry) => (
          <li
            key={entry.status}
            className='flex min-h-9 items-center gap-2.5 text-[13px]'
          >
            <StatusCell status={entry.status} size='sm' />
            <span className='w-16 shrink-0 font-medium'>
              {CELL_WORD[entry.status]}
            </span>
            <span className='text-muted-foreground min-w-0'>
              {entry.meaning}
            </span>
          </li>
        ))}
      </ul>
    </div>
  );
}

export default function AgentOps02() {
  const {
    ref,
    isInView,
    isAutoplaying,
    state,
    act,
    pressed,
    isFinished,
    restart,
  } = useSession(SESSION);
  const cases = CASES.filter((entry) => matchesFilter(state, entry));
  const isReady = canShip(state);
  const shipHint = shipHintOf(state);
  const message = spokenUnless(isAutoplaying, shipHint);
  const canReplay = isFinished && !isAutoplaying;
  const isLocked = state.ship !== 'idle';
  const shownWord = `${cases.length} of ${casesWordOf(CASES.length)}`;
  let openCase: EvalCase | null = null;
  if (state.openId !== null) {
    openCase = caseOf(state.openId);
  }

  function renderDetail(entry: EvalCase) {
    return (
      <CaseDetail
        entry={entry}
        candidateStatus={candidateStatusOf(state, entry.id)}
        isRegression={isRegression(state, entry.id)}
        verdict={state.verdicts[entry.id]}
        isLocked={isLocked}
        pressed={pressed}
        onVerdict={(verdict) => act({ type: 'verdict', id: entry.id, verdict })}
      />
    );
  }

  return (
    <ClockGate isActive={isInView}>
      <div
        ref={ref}
        className='bg-background text-foreground @container min-h-dvh w-full'
      >
        <div className='mx-auto flex max-w-6xl flex-col gap-4 p-4 @3xl:gap-5 @3xl:p-8'>
          <header className='flex flex-wrap items-center gap-x-3 gap-y-2'>
            <BrandTile brand={PROMPT.brand} size='lg' title={PROMPT.model} />
            <div className='flex min-w-40 flex-1 flex-col leading-tight'>
              <h1 className='text-lg font-semibold text-balance'>
                {PROMPT.name}
              </h1>
              <p className='text-muted-foreground text-xs'>
                {PROMPT.team} · {PROMPT.model}
              </p>
            </div>
            <ReplayButton
              isShown={canReplay}
              onReplay={restart}
              label='Replay the run'
            />
            <MorphButton
              type='button'
              state={RUN_STATE[state.phase]}
              labels={RUN_LABELS}
              idleIcon={<PlayIcon />}
              variant={runVariantOf(state.phase)}
              onClick={() => act({ type: 'run' })}
              className={pressedSolidOf(pressed === 'run')}
            />
          </header>

          <Versions state={state} />

          <div className='flex flex-col gap-4 @4xl:flex-row @4xl:items-start @4xl:gap-5'>
            <div className='flex min-w-0 flex-1 flex-col gap-3'>
              <div className='flex flex-wrap items-center justify-between gap-2'>
                <Segments
                  value={state.filter}
                  segments={FILTERS}
                  onValueChange={(filter) => act({ type: 'filter', filter })}
                  label='Show cases'
                  className='w-full @sm:w-72'
                />
                <span className='text-muted-foreground text-xs tabular-nums'>
                  {shownWord}
                </span>
              </div>
              <CaseGrid
                state={state}
                cases={cases}
                pressed={pressed}
                onOpen={(id) => act({ type: 'opened', id })}
                onShowAll={() => act({ type: 'filter', filter: 'all' })}
                renderDetail={renderDetail}
              />
              <div className='flex flex-wrap items-center justify-between gap-x-4 gap-y-2 px-1'>
                <p className='text-muted-foreground min-w-0 text-[13px]'>
                  <Swap swapKey={shipHint}>{shipHint}</Swap>
                </p>
                <MorphButton
                  type='button'
                  size='lg'
                  state={state.ship}
                  labels={SHIP_LABELS}
                  idleIcon={<RocketIcon />}
                  variant={shipVariantOf(isReady)}
                  disabled={!isReady}
                  onClick={() => act({ type: 'ship' })}
                  className={pressedSolidOf(pressed === 'ship')}
                />
              </div>
            </div>

            <aside
              aria-label='Case'
              className='bg-card hairline-ring ring-border dark:bg-foreground/[0.03] hidden w-[28rem] shrink-0 rounded-xl p-4 shadow-[0_1px_2px_rgb(0_0_0/0.04)] @4xl:block'
            >
              <AnimatedSize>
                {!openCase && <Legend />}
                {openCase && (
                  <div
                    key={openCase.id}
                    className='flex flex-col gap-3 transition-opacity duration-300 starting:opacity-0'
                  >
                    <div className='flex items-start justify-between gap-2'>
                      <h2 className='text-sm leading-7 font-medium'>
                        {openCase.name}
                      </h2>
                      <Button
                        type='button'
                        variant='ghost'
                        size='icon-sm'
                        aria-label='Close the case'
                        onClick={() => act({ type: 'closed' })}
                        className='text-muted-foreground'
                      >
                        <XIcon />
                      </Button>
                    </div>
                    {renderDetail(openCase)}
                  </div>
                )}
              </AnimatedSize>
            </aside>
          </div>
        </div>
        <LiveRegion message={message} />
      </div>
    </ClockGate>
  );
}

'use client';

import { MotionNumber } from '@/components/core/motion-number';
import { TrendingDownIcon, TrendingUpIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Badge } from '@/registry/ndeko/ui/badge';
import { Swap } from '@/registry/ndeko/ui/chat-motion';

import { CASES, TARGETS, type Target } from './data';
import {
  candidateRateOf,
  PRODUCTION_RATE,
  type EvalState,
  type PassRate,
} from './session';

type Change = {
  text: string;
  tone: string;
  trend: 'up' | 'down' | 'level';
};

function pointsOf(count: number) {
  if (count === 1) {
    return '1 point';
  }
  return `${count} points`;
}

function changeOf(candidate: PassRate): Change {
  const difference = candidate.percent - PRODUCTION_RATE.percent;
  const points = pointsOf(Math.abs(difference));
  if (difference < 0) {
    return {
      text: `${points} under production`,
      tone: 'text-warning-foreground',
      trend: 'down',
    };
  }
  if (difference > 0) {
    return {
      text: `${points} above production`,
      tone: 'text-success-foreground',
      trend: 'up',
    };
  }
  return {
    text: 'Level with production',
    tone: 'text-muted-foreground',
    trend: 'level',
  };
}

function candidateNoteOf(state: EvalState, rate: PassRate): Change {
  if (state.phase === 'idle') {
    return {
      text: 'Not compared with production yet',
      tone: 'text-muted-foreground',
      trend: 'level',
    };
  }
  if (state.phase === 'running') {
    return {
      text: `${state.landed} of ${CASES.length} cases run`,
      tone: 'text-muted-foreground',
      trend: 'level',
    };
  }
  return changeOf(rate);
}

/** While the run counts its cases the note stays in place; it swaps when its sentence changes. */
function noteKeyOf(state: EvalState, note: Change) {
  if (state.phase === 'running') {
    return 'running';
  }
  return note.text;
}

function productionNoteOf(isReplaced: boolean) {
  if (isReplaced) {
    return 'Kept for a rollback';
  }
  return 'Answers every conversation today';
}

function badgeWordOf(isLive: boolean, restingWord: string) {
  if (isLive) {
    return 'Live';
  }
  return restingWord;
}

function badgeVariantOf(isLive: boolean) {
  if (isLive) {
    return 'success';
  }
  return 'secondary';
}

function fillOf(percent: number) {
  const share = percent / 100;
  return { transform: `scaleX(${share})` };
}

type VersionCardProps = {
  target: Target;
  rate: PassRate | null;
  badgeWord: string;
  isLive: boolean;
  note: React.ReactNode;
};

function VersionCard({
  target,
  rate,
  badgeWord,
  isLive,
  note,
}: VersionCardProps) {
  const percent = rate?.percent ?? 0;

  return (
    <div className='bg-card hairline-ring ring-border dark:bg-foreground/[0.03] flex min-w-0 flex-col gap-2 rounded-xl p-4 shadow-[0_1px_2px_rgb(0_0_0/0.04)]'>
      <p className='flex flex-wrap items-center gap-x-2 gap-y-1'>
        <span className='text-[13px] font-medium'>{target.label}</span>
        <code className='text-muted-foreground font-mono text-xs'>
          {target.version}
        </code>
        <Badge
          variant={badgeVariantOf(isLive)}
          className='ms-auto transition-colors duration-300'
        >
          <Swap swapKey={badgeWord}>{badgeWord}</Swap>
        </Badge>
      </p>
      <div className='flex min-h-9 flex-wrap items-baseline gap-x-2'>
        {rate && (
          <>
            <MotionNumber
              value={rate.percent}
              suffix='%'
              className='text-[28px] leading-9 font-semibold'
            />
            <span className='text-muted-foreground text-xs tabular-nums'>
              {rate.passed} of {rate.total} passed
            </span>
          </>
        )}
        {!rate && (
          <span className='text-muted-foreground text-xl leading-9 font-medium'>
            Not run yet
          </span>
        )}
      </div>
      <div
        role='progressbar'
        aria-label={`${target.label} pass rate`}
        aria-valuemin={0}
        aria-valuemax={100}
        aria-valuenow={percent}
        className='bg-foreground/[0.06] h-1.5 overflow-hidden rounded-full'
      >
        <div
          style={fillOf(percent)}
          className='bg-success h-full origin-left rounded-full transition-transform duration-500 ease-(--ease-out-strong)'
        />
      </div>
      <div className='flex min-h-5 items-center text-xs'>{note}</div>
    </div>
  );
}

function TrendGlyph({ trend }: { trend: Change['trend'] }) {
  if (trend === 'up') {
    return <TrendingUpIcon className='size-3.5 shrink-0' />;
  }
  if (trend === 'down') {
    return <TrendingDownIcon className='size-3.5 shrink-0' />;
  }
  return null;
}

type VersionsProps = {
  state: EvalState;
};

export function Versions({ state }: VersionsProps) {
  const isShipped = state.ship === 'done';
  const hasFigure = state.landed > 0;
  const landedRate = candidateRateOf(state);
  let candidateRate: PassRate | null = null;
  if (hasFigure) {
    candidateRate = landedRate;
  }
  const candidateNote = candidateNoteOf(state, landedRate);
  const productionNote = productionNoteOf(isShipped);

  return (
    <div className='grid grid-cols-1 gap-3 @md:grid-cols-2'>
      <VersionCard
        target={TARGETS.production}
        rate={PRODUCTION_RATE}
        badgeWord={badgeWordOf(!isShipped, 'Previous')}
        isLive={!isShipped}
        note={
          <span className='text-muted-foreground'>
            <Swap swapKey={productionNote}>{productionNote}</Swap>
          </span>
        }
      />
      <VersionCard
        target={TARGETS.candidate}
        rate={candidateRate}
        badgeWord={badgeWordOf(isShipped, 'Candidate')}
        isLive={isShipped}
        note={
          <span
            className={cn(
              'tabular-nums transition-colors duration-200',
              candidateNote.tone
            )}
          >
            <Swap swapKey={noteKeyOf(state, candidateNote)}>
              <span className='flex items-center gap-1.5'>
                <TrendGlyph trend={candidateNote.trend} />
                {candidateNote.text}
              </span>
            </Swap>
          </span>
        }
      />
    </div>
  );
}

'use client';

import { AnimatePresence, motion } from 'motion/react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { rowPresenceOf } from '@/registry/ndeko/lib/motion-presets';
import { cn } from '@/registry/ndeko/lib/utils';
import { Badge } from '@/registry/ndeko/ui/badge';
import { Button } from '@/registry/ndeko/ui/button';
import { Swap } from '@/registry/ndeko/ui/chat-motion';

import { CELL_WORD, StatusCell } from './cells';
import { TARGETS, type EvalCase } from './data';
import {
  candidateStatusOf,
  isRegression,
  type CellStatus,
  type EvalState,
  type Filter,
  type Verdict,
} from './session';

const GRID =
  'grid grid-cols-[minmax(0,1fr)_2.75rem_2.75rem] items-center gap-2';

type RowMark = {
  word: string;
  variant: 'warning' | 'secondary' | 'destructive' | 'success';
};

const VERDICT_MARK: Record<Verdict, RowMark> = {
  accepted: { word: 'Accepted', variant: 'secondary' },
  blocked: { word: 'Blocked', variant: 'destructive' },
};

const REGRESSION_MARK: RowMark = { word: 'Regression', variant: 'warning' };

const FIXED_MARK: RowMark = { word: 'Fixed', variant: 'success' };

const EMPTY_LINE: Record<Filter, string> = {
  all: 'No case in this suite',
  failing: 'No case is failing',
  regressions:
    'No regression so far. They show here once the candidate has run',
};

function isFixedBy(entry: EvalCase, candidate: CellStatus) {
  const failedBefore = entry.production.outcome === 'fail';
  const passesNow = candidate === 'pass';
  return failedBefore && passesNow;
}

function rowMarkOf(state: EvalState, entry: EvalCase, candidate: CellStatus) {
  if (isRegression(state, entry.id)) {
    const verdict = state.verdicts[entry.id];
    if (verdict) {
      return VERDICT_MARK[verdict];
    }
    return REGRESSION_MARK;
  }
  if (isFixedBy(entry, candidate)) {
    return FIXED_MARK;
  }
  return null;
}

function rowLabelOf(
  entry: EvalCase,
  candidate: CellStatus,
  mark: RowMark | null
) {
  const production = CELL_WORD[entry.production.outcome].toLowerCase();
  const candidateWord = CELL_WORD[candidate].toLowerCase();
  const summary = `${entry.name}: production ${production}, candidate ${candidateWord}`;
  if (mark) {
    return `${summary}, ${mark.word.toLowerCase()}`;
  }
  return summary;
}

function rowToneOf(isOpen: boolean) {
  if (isOpen) {
    return 'bg-foreground/[0.05]';
  }
  return 'hover:bg-foreground/[0.03]';
}

function pressedQuietOf(isPressed: boolean) {
  if (isPressed) {
    return 'scale-[0.985] bg-foreground/[0.07]';
  }
  return undefined;
}

/** The arrow keys walk the rows; Tab still reaches the buttons inside an open case. */
function moveBetweenRows(event: React.KeyboardEvent<HTMLUListElement>) {
  const isDown = event.key === 'ArrowDown';
  const isUp = event.key === 'ArrowUp';
  if (!isDown && !isUp) {
    return;
  }
  const found =
    event.currentTarget.querySelectorAll<HTMLElement>('[data-case]');
  const rows = Array.from(found);
  const current = rows.findIndex((row) => row === document.activeElement);
  if (current === -1) {
    return;
  }
  let next = current - 1;
  if (isDown) {
    next = current + 1;
  }
  const target = rows[next];
  if (target) {
    event.preventDefault();
    target.focus();
  }
}

type CaseRowProps = {
  entry: EvalCase;
  state: EvalState;
  isPressed: boolean;
  onOpen: (id: string) => void;
  renderDetail: (entry: EvalCase) => React.ReactNode;
};

function CaseRow({
  entry,
  state,
  isPressed,
  onOpen,
  renderDetail,
}: CaseRowProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const rowPresence = rowPresenceOf(shouldReduceMotion);
  const candidate = candidateStatusOf(state, entry.id);
  const mark = rowMarkOf(state, entry, candidate);
  const isOpen = state.openId === entry.id;

  return (
    <>
      <button
        type='button'
        data-case={entry.id}
        aria-expanded={isOpen}
        aria-label={rowLabelOf(entry, candidate, mark)}
        onClick={() => onOpen(entry.id)}
        className={cn(
          GRID,
          'focus-visible:ring-ring/25 min-h-9 w-full cursor-pointer rounded-lg px-2 py-1 text-start transition-[background-color,scale] duration-150 outline-none focus-visible:ring-[3px] focus-visible:ring-inset',
          rowToneOf(isOpen),
          pressedQuietOf(isPressed)
        )}
      >
        <span className='flex min-w-0 items-center gap-2'>
          <span className='truncate text-[13px]'>{entry.name}</span>
          {mark && (
            <Badge
              variant={mark.variant}
              className='transition-colors duration-300 starting:opacity-0'
            >
              <Swap swapKey={mark.word}>{mark.word}</Swap>
            </Badge>
          )}
        </span>
        <span className='flex justify-center'>
          <StatusCell status={entry.production.outcome} />
        </span>
        <span className='flex justify-center'>
          <StatusCell status={candidate} />
        </span>
      </button>
      <AnimatePresence initial={false}>
        {isOpen && (
          <motion.div
            key='detail'
            className='overflow-hidden @4xl:hidden'
            {...rowPresence}
          >
            <div className='px-2 pt-2 pb-3'>{renderDetail(entry)}</div>
          </motion.div>
        )}
      </AnimatePresence>
    </>
  );
}

type CaseGridProps = {
  state: EvalState;
  cases: EvalCase[];
  pressed: string | null;
  onOpen: (id: string) => void;
  onShowAll: () => void;
  renderDetail: (entry: EvalCase) => React.ReactNode;
};

export function CaseGrid({
  state,
  cases,
  pressed,
  onOpen,
  onShowAll,
  renderDetail,
}: CaseGridProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const rowPresence = rowPresenceOf(shouldReduceMotion);
  const isEmpty = cases.length === 0;

  return (
    <section
      aria-label='Cases'
      className='bg-card hairline-ring ring-border dark:bg-foreground/[0.03] flex flex-col rounded-xl p-1 shadow-[0_1px_2px_rgb(0_0_0/0.04)]'
    >
      <div
        aria-hidden='true'
        className={cn(GRID, 'text-muted-foreground h-8 px-2 text-xs')}
      >
        <span>Case</span>
        <span className='text-center font-mono'>
          {TARGETS.production.version}
        </span>
        <span className='text-center font-mono'>
          {TARGETS.candidate.version}
        </span>
      </div>
      <ul className='flex flex-col' onKeyDown={moveBetweenRows}>
        <AnimatePresence initial={false}>
          {cases.map((entry) => (
            <motion.li
              key={entry.id}
              className='overflow-hidden'
              {...rowPresence}
            >
              <CaseRow
                entry={entry}
                state={state}
                isPressed={pressed === `case-${entry.id}`}
                onOpen={onOpen}
                renderDetail={renderDetail}
              />
            </motion.li>
          ))}
        </AnimatePresence>
      </ul>
      {isEmpty && (
        <div className='flex flex-col items-start gap-3 px-2 pt-1 pb-3 transition-opacity duration-300 starting:opacity-0'>
          <p className='text-muted-foreground text-[13px]'>
            {EMPTY_LINE[state.filter]}
          </p>
          <Button type='button' variant='outline' size='sm' onClick={onShowAll}>
            Show all cases
          </Button>
        </div>
      )}
    </section>
  );
}

'use client';

