    <div className='flex flex-col gap-2'>
      {isUndecided && (
        <div className='flex flex-wrap items-center gap-2'>
          <Button
            type='button'
            size='sm'
            onClick={() => onVerdict('accepted')}
            className={pressedSolidOf(isAcceptPressed)}
